import json
CHAR = "Flat 2D cartoon: a simple white character with a big round head, a small soft body, noodle arms with simple four-finger hands and short legs with rounded feet, thick smooth black (#000000) outlines of even weight, about 2 % of the head width thick, flat white fill (#FEFDFD) with a very soft pale-grey shade (#EDEBEB) on the left side of the head and body, the round head is wider than the body and about 0.38 of the full body height, small solid black vertical oval eyes about one sixth of the head width tall, simple curved black eyebrows, no nose, no hair, no clothes, a pink tongue (#FC8D90) only when the mouth is open. Clean vector-like linework, flat colours, no texture, no text, no border."
OBJ = "Flat 2D cartoon in the same drawing style: bold clean thick smooth black outlines of even weight, flat colours with one simple soft shade, clean vector-like linework, simple shapes, no texture, no text, no border, no characters."
def KEY(c='green'):
    col = 'pure green (#00FF00)' if c == 'green' else 'pure magenta (#FF00FF)'
    return f"Isolated on a perfectly flat, uniform, solid {col} background that fills the whole picture edge to edge: no shadow, no ground, no floor line, no gradient, no vignette, no border, no other objects. The whole subject in frame with a clear margin on every side."
BG = "Flat 2D cartoon background in the same drawing style: big simple flat-colour shapes, thick smooth black outlines only on the main shapes, no texture, no text, no labels, no arrows, no characters, calm and simple so a character reads clearly on top of it."
TWO = "Two DIFFERENT poses of the same character side by side with a wide gap between them, both full body, bold clean thick outlines. "
BRO = " This character is the twin brother: exactly the same simple white character, wearing only small round black-rimmed glasses - nothing else added, no hair, no clothes."
P = {
 'hero': ("2:3", "Full body, side view facing to the RIGHT, standing up very straight and tall with a proud straight back, arms hanging down at the sides, a calm happy closed-mouth smile. Whole body in frame with a margin. Bold clean thick outlines. " + CHAR + " " + KEY()),
 'bro2': ("3:2", TWO + "LEFT copy: side view facing to the LEFT, standing up very straight and tall with a proud straight back, arms hanging down at the sides, a calm happy closed-mouth smile. RIGHT copy: facing the viewer, head tilted back looking UP in shock, eyebrows raised high, wide eyes, mouth wide open with the pink tongue showing, both hands on the cheeks. Whole bodies in frame with a margin. " + CHAR + BRO + " " + KEY()),
 'astro2': ("3:2", TWO + "LEFT copy: floating weightless lying horizontally in the air, body stretched out long, both arms stretched above the head to the LEFT, legs to the RIGHT, eyes closed with a blissful relaxed smile. RIGHT copy: standing facing the viewer, proud and puffed-up, chest out, both fists on the hips, big confident open grin with the pink tongue showing, eyebrows raised. Whole bodies in frame with a margin. " + CHAR + " " + KEY()),
 'weak2': ("3:2", TWO + "LEFT copy: facing the viewer, weak and wobbly, knees bent and knocking together, arms hanging limp, back slumped, worried face: eyebrows tilted up in the middle, wide eyes, small wavy mouth. RIGHT copy: facing the viewer, squashed down under a heavy weight, knees bent, both arms raised up with open hands pushing against something above the head (nothing drawn above), eyes squeezed shut, teeth gritted. Whole bodies in frame with a margin. " + CHAR + " " + KEY()),
 'rocket': ("2:3", "One small cheerful cartoon space rocket standing upright: a white rounded body, a red pointed nose cone, three red fins at the bottom, one round blue porthole window in the middle, a grey nozzle at the bottom, no flame, no smoke. Bold clean thick outlines. " + OBJ + " " + KEY('magenta')),
 'home': ("2:3", "A simple cosy room seen from the front, vertical picture: a flat pale-yellow wall filling the top 70 % with one small square window on the far right showing blue sky, a light wooden floor in the bottom 30 % with a dark baseboard line, a small green potted plant in the far left corner. The middle of the wall is completely empty and plain. No people, no furniture in the middle, no pictures on the wall. " + BG),
 'space': ("2:3", "Outer space, vertical picture: a deep dark-navy sky with a few small simple white four-point stars, the big blue-and-green planet Earth filling the bottom 35 % of the picture as a huge curved horizon with simple flat continents and a thin light-blue glow line, and a small simple grey space station with flat blue solar panels far away in the upper right. No people, no rockets, no text. " + BG),
}
json.dump(P, open('prompts.json', 'w'), indent=1)
with open('prompts.md', 'w') as f:
    f.write('# space-twin - picture prompts (all gpt-image-2.5-sunburst, 1K, quality LOW, 1 variation, no references)\n\n')
    for k, (ar, p) in P.items(): f.write(f'## {k} ({ar})\n{p}\n\n')
print('ok', len(P))
